create or replace function pg_temp.reject_home_activity() returns trigger language plpgsql as $$
begin
  if new.kind='household_record_changed' and new.entity_id='26000000-0000-4000-8000-000000000014' then
    raise exception 'injected parent activity failure' using errcode='23514';
  end if;
  return new;
end $$;
set local role authenticated;
select throws_ok($$select public.choose_household_decision_option('26000000-0000-4000-8000-000000000014',null)$$,'23514','injected parent activity failure','late parent activity failure aborts the entire choice command');
select is((select chosen from public.decision_options where id='26000000-0000-4000-8000-000000000015'),true,'late failure restores the option already changed by the command');
select is((select status from public.household_decisions where id='26000000-0000-4000-8000-000000000014'),'decided','late failure preserves decision status');
select is((select count(*) from public.activity_events where entity_id in ('26000000-0000-4000-8000-000000000014','26000000-0000-4000-8000-000000000015') and payload->>'operation'='updated'),4::bigint,'late failure rolls back the earlier option activity as well');
select * from finish();
rollback;
